// Unit 1, Essential Grammar in Use 4th ed., printed pp.12–13; key p.283.
export const sections=['1.1 缩写形式','1.2 am / is / are','1.3 补全句子','1.4 介绍自己','1.5 看图造句','1.6 肯定与否定'];
const rows=[
[['she is',["she’s"]],['they are',["they’re"]],['it is not',["it isn’t","it’s not"]],['that is',["that’s"]],['I am not',["I’m not"]],['you are not',["you aren’t","you’re not"]]],
[['The weather ___ nice today.',['is']],['I ___ not rich.',['am',"'m"]],['This bag ___ heavy.',['is']],['These bags ___ heavy.',['are']],['Look! There ___ Helen.',['is',"'s"]],['My brother and I ___ good tennis players.',['are']],['Emily ___ at home. Her children ___ at school.',['is / are']],['I ___ a taxi driver. My sister ___ a nurse.',['am / is',"'m / is"]]],
[['Steve is ill. ___ in bed.',["He’s","He is"]],["I’m not hungry, but ___ thirsty.",["I’m","I am"]],['Mr Thomas is a very old man. ___ 98.',["He’s","He is"]],["These chairs aren’t beautiful, but ___ comfortable.",["they’re","they are"]],['The weather is nice today. ___ warm and sunny.',["It’s","It is"]],["‘___ late.’ ‘No, I’m not. I’m early!’",["You’re","You are"]],["Catherine isn’t at home. ___ at work.",["She’s","She is"]],["‘___ your coat.’ ‘Oh, thank you very much.’",["Here’s","Here is"]]],
[['介绍你的名字。',['My name is Robert.'],'My name is …'],['介绍你的年龄。',["I’m 25."],'I am …'],['介绍你来自哪里。',["I’m from Australia."],'I am from …'],['介绍你的职业。',["I’m a gardener."],'I am a/an …'],['介绍你最喜欢的颜色。',['My favourite colours are black and white.'],'My favourite colour is … / My favourite colours are …'],['介绍你的兴趣。',["I’m interested in plants."],'I am interested in …']],
[['图 1：用 she 和 thirsty 造句。',["She’s thirsty.",'She is thirsty.']],['图 2：用 they 和 cold 造句。',["They’re cold.",'They are cold.']],['图 3：用 he 和 hot 造句。',["He’s hot.",'He is hot.']],['图 4：用 he 和 scared 造句。',["He’s scared.",'He is scared.']],['图 5：用 they 和 hungry 造句。',["They’re hungry.",'They are hungry.']],['图 6：用 she 和 angry 造句。',["She’s angry.",'She is angry.']]],
[['it / hot today',['It is hot today.','It is not hot today.']],['it / windy today',['It is windy today.','It is not windy today.']],['my hands / cold',['My hands are cold.','My hands are not cold.']],['Brazil / a very big country',['Brazil is a very big country.']],['diamonds / cheap',['Diamonds are not cheap.']],['Toronto / in the US',['Toronto is not in the US.']],['tired',['I am tired.','I am not tired.']],['hungry',['I am hungry.','I am not hungry.']],['a good swimmer',['I am a good swimmer.','I am not a good swimmer.']],['interested in football',['I am interested in football.','I am not interested in football.']]]];
export const bookQuestions=rows.flatMap((r,group)=>r.map(([prompt,answers,frame],i)=>({id:`book-${group}-${i}`,group,prompt,answers,frame,personal:!!frame,explanation:group===0?'缩写必须保留撇号；I am not 只能缩写为 I’m not。':group===1?'I 用 am；单数主语用 is；you 和复数主语用 are。两个空请用 / 分隔。':group===2?'补上合适的主语与 be 动词；here is 表示“这是／给你”。':group===3?'这是个人表达：参考答案只示范结构，不要求与你的个人信息一致。':group===4?'先判断图中人物的单复数，再用 be + 表示状态的形容词。':'否定在 be 后加 not。天气、感受和个人能力按实际情况选择肯定或否定；接受常见缩写。'})));
// Independently authored parallel set; never labelled as book questions.
export const extraQuestions=[['we are',["we’re"]],['he is not',["he isn’t","he’s not"]],['My friends ___ here.',['are']],['I ___ ready.',['am']],['Anna is a nurse. ___ at work.',["She is","She’s"]],['These shoes are new. ___ expensive.',["They are","They’re"]],['介绍你的名字。',['My name is Alex.'],'My name is …'],['介绍你的兴趣。',['I am interested in music.'],'I am interested in …'],['用 she / tired 写一句话。',['She is tired.']],['用 they / happy 写一句话。',['They are happy.']],['否定句：The room is cold.',['The room is not cold.']],['否定句：We are late.',['We are not late.']]].map(([prompt,answers,frame],i)=>({id:`extra-${i}`,group:Math.floor(i/2),prompt,answers,frame,personal:!!frame,explanation:'原创巩固题：检查主语与 am / is / are 是否一致；否定使用 not。'}));
export const normalize=s=>s.trim().toLowerCase().replace(/[’‘]/g,"'").replace(/\b(i'm|he's|she's|it's|they're|we're|you're|that's|here's|there's|isn't|aren't)\b/g,m=>({"i'm":"i am","he's":"he is","she's":"she is","it's":"it is","they're":"they are","we're":"we are","you're":"you are","that's":"that is","here's":"here is","there's":"there is","isn't":"is not","aren't":"are not"}[m])).replace(/[.!?]+$/,'').replace(/\s*\/\s*/g,' / ').replace(/\s+/g,' ');
export function correct(q,value){if(q.personal)return null;if(q.group===0)return q.answers.some(a=>a.replace(/[’‘]/g,"'").toLowerCase()===value.trim().replace(/[’‘]/g,"'").toLowerCase());return q.answers.some(a=>normalize(a)===normalize(value));}
export const initialUnit1=()=>({view:'lesson',step:0,set:0,index:0,drafts:{},answers:{}});
export const unitQuestions=s=>s.set===0?bookQuestions:extraQuestions;
export function validateUnit1(s){if(s===undefined)return;const fail=()=>{throw Error('Unit 1 进度格式无效。');};if(!s||!['lesson','practice','result'].includes(s.view)||!Number.isInteger(s.step)||s.step<0||s.step>2||!Number.isSafeInteger(s.set)||s.set<0||!Number.isInteger(s.index)||s.index<0||s.index>=unitQuestions(s).length)fail();for(const key of ['drafts','answers'])if(!s[key]||typeof s[key]!=='object'||Array.isArray(s[key]))fail();const map=Object.fromEntries([...bookQuestions,...extraQuestions].map(q=>[q.id,q]));for(const[id,v]of Object.entries(s.drafts))if(!map[id]||typeof v!=='string'||v.length>500)fail();for(const[id,a]of Object.entries(s.answers))if(!map[id]||!a||typeof a.value!=='string'||!a.value.trim()||a.value.length>500||a.correct!==correct(map[id],a.value)||typeof a.checked!=='boolean'||(!map[id].personal&&a.checked))fail();if(s.view==='result'&&!unitQuestions(s).every(q=>s.answers[q.id]&&(!q.personal||s.answers[q.id].checked)))fail();return s;}
export function submitUnit1(s){const q=unitQuestions(s)[s.index],value=(s.drafts[q.id]||'').trim();if(s.answers[q.id])throw Error('本题已提交。');if(!value)throw Error('请先填写答案。');s.answers[q.id]={value,correct:correct(q,value),checked:false};}
export function nextUnit1(s){const q=unitQuestions(s)[s.index],a=s.answers[q.id];if(!a||q.personal&&!a.checked)throw Error('请先提交并完成个人表达自查。');if(s.index===unitQuestions(s).length-1)s.view='result';else s.index++;}
